package com.nutribite.ai.health.service;
import com.nutribite.ai.health.calculator.*; import com.nutribite.ai.health.dto.HealthMetricsResponse; import com.nutribite.ai.health.util.HealthUtils; import com.nutribite.ai.model.User; import com.nutribite.ai.profile.entity.UserProfile; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class HealthServiceImpl implements HealthService {private final BMICalculator bmiCalculator;private final BMRCalculator bmrCalculator;private final TDEECalculator tdeeCalculator;private final CalorieCalculator calorieCalculator;private final HealthUtils healthUtils; public HealthMetricsResponse calculate(User user,UserProfile profile){int age=healthUtils.calculateAge(profile.getDateOfBirth());double bmi=bmiCalculator.calculateBMI(profile.getWeightKg(),profile.getHeightCm());double ideal=bmiCalculator.calculateIdealWeight(profile.getHeightCm());double bmr=bmrCalculator.calculate(user.getGender(),profile.getWeightKg(),profile.getHeightCm(),age);double tdee=tdeeCalculator.calculate(bmr,profile.getActivityLevel());double calories=Math.max(1200,calorieCalculator.calculate(tdee,profile.getGoal()));return HealthMetricsResponse.builder().age(age).bmi(healthUtils.round(bmi)).bmiCategory(bmiCalculator.getCategory(bmi)).idealWeight(healthUtils.round(ideal)).bmr(healthUtils.round(bmr)).tdee(healthUtils.round(tdee)).recommendedCalories(healthUtils.round(calories)).build();}}
